package com.dorm.platform.system.service;

import com.dorm.platform.common.*;
import com.dorm.platform.security.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.dorm.platform.common.Input.*;
import static com.dorm.platform.common.BizException.require;

@Service
public class ManagementService {
 private final SqlStore db; private final DataScope scope;
 public ManagementService(SqlStore db,DataScope scope){this.db=db;this.scope=scope;}
 public List<Map<String,Object>> homes(CurrentUser u,boolean history){role(u,"STUDENT","DORM_MANAGER","ADMIN");String filter=u.role().equals("STUDENT")?"a.student_user_id="+u.id():scope.buildingFilter(u,"r.building_id");return db.rows("SELECT a.*,u.real_name student_name,b.building_id,b.building_name,r.room_id,r.room_no,bd.bed_no FROM accommodation_assignment a JOIN sys_user u ON u.user_id=a.student_user_id JOIN bed bd ON bd.bed_id=a.bed_id JOIN dorm_room r ON r.room_id=bd.room_id JOIN building b ON b.building_id=r.building_id WHERE "+filter+(history?"":" AND a.check_in_date<=CURRENT_DATE() AND (a.check_out_date IS NULL OR a.check_out_date>CURRENT_DATE())")+" ORDER BY a.assignment_id DESC");}
 public List<Map<String,Object>> roommates(CurrentUser u){role(u,"STUDENT");return db.rows("SELECT student_name,bed_no FROM v_accommodation_current WHERE room_id IN (SELECT room_id FROM v_accommodation_current WHERE student_user_id=?) AND student_user_id<>?",u.id(),u.id());}
 public List<Map<String,Object>> buildings(CurrentUser u){role(u,"STUDENT","DORM_MANAGER","ADMIN");String filter=u.role().equals("STUDENT")?"b.building_id IN (SELECT building_id FROM v_accommodation_current WHERE student_user_id="+u.id()+")":scope.buildingFilter(u,"b.building_id");return db.rows("SELECT b.*,COUNT(DISTINCT r.room_id) room_count,COUNT(bd.bed_id) bed_count,(SELECT COUNT(*) FROM v_accommodation_current a WHERE a.building_id=b.building_id) occupied_count FROM building b LEFT JOIN dorm_room r ON r.building_id=b.building_id LEFT JOIN bed bd ON bd.room_id=r.room_id WHERE "+filter+" GROUP BY b.building_id ORDER BY b.building_code");}
 public List<Map<String,Object>> rooms(CurrentUser u){role(u,"DORM_MANAGER","ADMIN");return db.rows("SELECT r.*,b.building_name FROM dorm_room r JOIN building b ON b.building_id=r.building_id WHERE "+scope.buildingFilter(u,"r.building_id")+" ORDER BY r.building_id,r.room_no");}
 public List<Map<String,Object>> beds(CurrentUser u){role(u,"DORM_MANAGER","ADMIN");return db.rows("SELECT bd.*,r.building_id,r.room_no,b.building_name,a.student_name,a.student_user_id FROM bed bd JOIN dorm_room r ON r.room_id=bd.room_id JOIN building b ON b.building_id=r.building_id LEFT JOIN v_accommodation_current a ON a.bed_id=bd.bed_id WHERE "+scope.buildingFilter(u,"r.building_id")+" ORDER BY b.building_id,r.room_no,bd.bed_no");}
 public List<Map<String,Object>> users(CurrentUser u){role(u,"ADMIN");var list=db.rows("SELECT user_id,login_account,real_name,phone,role_code,enabled,created_at FROM sys_user ORDER BY user_id");for(var row:list){row.put("buildingIds",db.rows("SELECT building_id FROM manager_building_scope WHERE manager_user_id=?",row.get("user_id")).stream().map(x->x.get("building_id")).toList());}return list;}
 public Map<String,Object> profile(CurrentUser u){return db.one("SELECT login_account,real_name,phone,role_code FROM sys_user WHERE user_id=?",u.id());}
 @Transactional public void profile(CurrentUser u,Map<String,Object>b){String phone=required(b,"phone");require(phone.matches("[+0-9 -]{5,30}"),"联系方式格式不正确");db.update("UPDATE sys_user SET phone=? WHERE user_id=?",phone,u.id());db.log(u.id(),"auth","profile",u.id());}
 @Transactional public void password(CurrentUser u,Map<String,Object>b){String old=required(b,"oldPassword"),next=required(b,"newPassword");require(next.length()>=6&&next.length()<=100,"密码长度必须为6到100位");require(db.count("SELECT COUNT(*) FROM sys_user WHERE user_id=? AND password_hash=?",u.id(),AuthService.sha256(old))==1,"原密码错误");db.update("UPDATE sys_user SET password_hash=? WHERE user_id=?",AuthService.sha256(next),u.id());db.log(u.id(),"auth","password",u.id());}
 @Transactional public long saveUser(CurrentUser u,Long userId,Map<String,Object>b){role(u,"ADMIN");String role=required(b,"roleCode");require(Set.of("STUDENT","DORM_MANAGER","REPAIRER","ADMIN").contains(role),"角色无效");String name=required(b,"realName");long user;if(userId==null){String password=required(b,"password");require(password.length()>=6,"密码至少6位");user=db.insert("INSERT INTO sys_user(login_account,password_hash,real_name,phone,role_code) VALUES(?,?,?,?,?)",required(b,"account"),AuthService.sha256(password),name,text(b,"phone"),role);}else{user=userId;var old=db.one("SELECT * FROM sys_user WHERE user_id=? FOR UPDATE",user);require(user!=u.id()||role.equals("ADMIN"),"不能移除自己的管理员角色");if(!role.equals(old.get("role_code")))require(db.count("SELECT (SELECT COUNT(*) FROM repair_order WHERE student_user_id=?)+(SELECT COUNT(*) FROM repair_dispatch WHERE repairer_user_id=?)+(SELECT COUNT(*) FROM accommodation_assignment WHERE student_user_id=?)+(SELECT COUNT(*) FROM stay_application WHERE student_user_id=?)",user,user,user,user)==0,"已有业务历史的账号不能变更角色");db.update("UPDATE sys_user SET real_name=?,phone=?,role_code=? WHERE user_id=?",name,text(b,"phone"),role,user);if(!text(b,"password").isBlank()){require(text(b,"password").length()>=6,"密码至少6位");db.update("UPDATE sys_user SET password_hash=? WHERE user_id=?",AuthService.sha256(text(b,"password")),user);}}db.update("DELETE FROM manager_building_scope WHERE manager_user_id=?",user);if(role.equals("DORM_MANAGER")){for(Object building:(b.get("buildingIds") instanceof List<?> values?values:List.of()))db.update("INSERT INTO manager_building_scope(manager_user_id,building_id) VALUES(?,?)",user,id(building));}if(role.equals("REPAIRER"))db.update("INSERT IGNORE INTO repairer_profile(repairer_user_id) VALUES(?)",user);db.log(u.id(),"auth",userId==null?"create":"update",user);return user;}
 @Transactional public void enabled(CurrentUser u,long user,boolean enabled){role(u,"ADMIN");require(user!=u.id()||enabled,"不能禁用自己的账号");db.one("SELECT user_id FROM sys_user WHERE user_id=? FOR UPDATE",user);db.update("UPDATE sys_user SET enabled=? WHERE user_id=?",enabled,user);db.log(u.id(),"auth",enabled?"enable":"disable",user);}
 @Transactional public void deleteUser(CurrentUser u,long user){role(u,"ADMIN");require(user!=u.id(),"不能删除自己的账号");require(db.count("SELECT (SELECT COUNT(*) FROM repair_order WHERE student_user_id=?)+(SELECT COUNT(*) FROM repair_dispatch WHERE repairer_user_id=?)+(SELECT COUNT(*) FROM accommodation_assignment WHERE student_user_id=?)+(SELECT COUNT(*) FROM stay_application WHERE student_user_id=?)",user,user,user,user)==0,"账号存在业务记录，只能停用以保留历史");db.update("DELETE FROM manager_building_scope WHERE manager_user_id=?",user);db.update("DELETE FROM repairer_work_type WHERE repairer_user_id=?",user);db.update("DELETE FROM repairer_building_scope WHERE repairer_user_id=?",user);db.update("DELETE FROM repairer_profile WHERE repairer_user_id=?",user);db.update("DELETE FROM message_receipt WHERE user_id=?",user);db.update("DELETE FROM message_target WHERE user_id=?",user);db.update("DELETE FROM sys_user WHERE user_id=?",user);db.log(u.id(),"auth","delete",user);}
 @Transactional public long resource(CurrentUser u,String type,Long resourceId,Map<String,Object>b){role(u,"ADMIN");long n;switch(type){case "buildings":if(resourceId==null)n=db.insert("INSERT INTO building(building_code,building_name,address,gender_limit) VALUES(?,?,?,?)",required(b,"buildingCode"),required(b,"buildingName"),required(b,"address"),required(b,"genderLimit"));else{n=resourceId;db.update("UPDATE building SET building_code=?,building_name=?,address=?,gender_limit=? WHERE building_id=?",required(b,"buildingCode"),required(b,"buildingName"),required(b,"address"),required(b,"genderLimit"),n);}break;case "rooms":long capacity=id(b.get("designCapacity"));require(capacity>0,"房间容量必须大于0");if(resourceId==null)n=db.insert("INSERT INTO dorm_room(building_id,room_no,floor_no,design_capacity) VALUES(?,?,?,?)",id(b.get("buildingId")),required(b,"roomNo"),id(b.get("floorNo")),capacity);else{n=resourceId;require(db.count("SELECT COUNT(*) FROM bed WHERE room_id=?",n)<=capacity,"容量不能少于已建床位数");db.update("UPDATE dorm_room SET room_no=?,floor_no=?,design_capacity=? WHERE room_id=?",required(b,"roomNo"),id(b.get("floorNo")),capacity,n);}break;case "beds":long room=id(b.get("roomId"));var r=db.one("SELECT * FROM dorm_room WHERE room_id=? FOR UPDATE",room);String status=required(b,"managementStatus");require(Set.of("AVAILABLE","DISABLED").contains(status),"床位状态无效");if(resourceId==null){require(db.count("SELECT COUNT(*) FROM bed WHERE room_id=?",room)<id(r.get("design_capacity")),"床位数已达到房间容量");n=db.insert("INSERT INTO bed(room_id,bed_no,management_status) VALUES(?,?,?)",room,required(b,"bedNo"),status);}else{n=resourceId;require(!status.equals("DISABLED")||db.count("SELECT COUNT(*) FROM v_accommodation_current WHERE bed_id=?",n)==0,"已分配床位不能停用");db.update("UPDATE bed SET bed_no=?,management_status=? WHERE bed_id=?",required(b,"bedNo"),status,n);}break;default:throw new BizException(404,"未知资源");}db.log(u.id(),"dorm",type,n);return n;}
 @Transactional public void assign(CurrentUser u,Map<String,Object>b){role(u,"ADMIN");long student=id(b.get("studentUserId")),bed=id(b.get("bedId"));db.one("SELECT user_id FROM sys_user WHERE user_id=? AND role_code='STUDENT' AND enabled=1 FOR UPDATE",student);var target=db.one("SELECT * FROM bed WHERE bed_id=? FOR UPDATE",bed);require("AVAILABLE".equals(target.get("management_status")),"床位已停用");require(db.count("SELECT COUNT(*) FROM v_accommodation_current WHERE bed_id=?",bed)==0,"床位已占用");db.update("UPDATE accommodation_assignment SET check_out_date=CURRENT_DATE() WHERE student_user_id=? AND check_out_date IS NULL",student);long assignment=db.insert("INSERT INTO accommodation_assignment(student_user_id,bed_id,check_in_date,assignment_type) VALUES(?,?,CURRENT_DATE(),'ASSIGN')",student,bed);db.log(u.id(),"dorm","assign",assignment);}
 @Transactional public void checkout(CurrentUser u,long assignment){role(u,"ADMIN");require(db.update("UPDATE accommodation_assignment SET check_out_date=CURRENT_DATE() WHERE assignment_id=? AND check_out_date IS NULL",assignment)==1,"当前记录已退宿");db.log(u.id(),"dorm","checkout",assignment);}
 public Map<String,Object> config(CurrentUser u){role(u,"ADMIN");var workers=db.rows("SELECT p.*,u.real_name FROM repairer_profile p JOIN sys_user u ON u.user_id=p.repairer_user_id");for(var w:workers){w.put("workTypeIds",db.rows("SELECT work_type_id FROM repairer_work_type WHERE repairer_user_id=?",w.get("repairer_user_id")).stream().map(x->x.get("work_type_id")).toList());w.put("buildingIds",db.rows("SELECT building_id FROM repairer_building_scope WHERE repairer_user_id=?",w.get("repairer_user_id")).stream().map(x->x.get("building_id")).toList());}return Map.of("rule",db.one("SELECT * FROM repair_rule ORDER BY rule_id DESC LIMIT 1"),"workers",workers,"categories",db.rows("SELECT * FROM fault_category"),"workTypes",db.rows("SELECT * FROM repair_work_type"));}
 @Transactional public void saveRule(CurrentUser u,Map<String,Object>b){role(u,"ADMIN");for(String key:List.of("accept_minutes","normal_minutes","urgent_minutes","confirm_days","edit_days"))require(id(b.get(key))>0,"时限必须大于0");Object max=text(b,"max_rework_count").isBlank()?null:id(b.get("max_rework_count"));require(max==null||id(max)>=0,"重修次数不能小于0");long n=db.insert("INSERT INTO repair_rule(accept_minutes,normal_minutes,urgent_minutes,confirm_days,edit_days,max_rework_count) VALUES(?,?,?,?,?,?)",id(b.get("accept_minutes")),id(b.get("normal_minutes")),id(b.get("urgent_minutes")),id(b.get("confirm_days")),id(b.get("edit_days")),max);db.log(u.id(),"repair","rule_version",n);}
 @Transactional public void worker(CurrentUser u,long worker,Map<String,Object>b){role(u,"ADMIN");db.one("SELECT repairer_user_id FROM repairer_profile WHERE repairer_user_id=? FOR UPDATE",worker);Object max=text(b,"maxActiveOrders").isBlank()?null:id(b.get("maxActiveOrders"));require(max==null||id(max)>0,"最大在办数必须大于0");db.update("UPDATE repairer_profile SET on_duty=?,max_active_orders=? WHERE repairer_user_id=?",flag(b,"onDuty"),max,worker);db.update("DELETE FROM repairer_work_type WHERE repairer_user_id=?",worker);db.update("DELETE FROM repairer_building_scope WHERE repairer_user_id=?",worker);for(Object v:(b.get("workTypeIds") instanceof List<?> a?a:List.of()))db.update("INSERT INTO repairer_work_type(repairer_user_id,work_type_id) VALUES(?,?)",worker,id(v));for(Object v:(b.get("buildingIds") instanceof List<?> a?a:List.of()))db.update("INSERT INTO repairer_building_scope(repairer_user_id,building_id) VALUES(?,?)",worker,id(v));db.log(u.id(),"repair","worker_scope",worker);}
 @Transactional public void dictionary(CurrentUser u,String type,Long n,Map<String,Object>b){role(u,"ADMIN");if(type.equals("work-types")){if(n==null)db.update("INSERT INTO repair_work_type(work_type_code,work_type_name) VALUES(?,?)",required(b,"code"),required(b,"name"));else db.update("UPDATE repair_work_type SET work_type_name=?,enabled=? WHERE work_type_id=?",required(b,"name"),flag(b,"enabled"),n);}else if(type.equals("categories")){if(n==null)db.update("INSERT INTO fault_category(work_type_id,category_name) VALUES(?,?)",id(b.get("workTypeId")),required(b,"name"));else db.update("UPDATE fault_category SET category_name=?,work_type_id=?,enabled=? WHERE category_id=?",required(b,"name"),id(b.get("workTypeId")),flag(b,"enabled"),n);}else throw new BizException(404,"未知字典");db.log(u.id(),"repair",type,n==null?0:n);}
 public List<Map<String,Object>> logs(CurrentUser u){role(u,"ADMIN");return db.rows("SELECT l.*,u.real_name FROM operation_log l LEFT JOIN sys_user u ON u.user_id=l.operator_user_id ORDER BY log_id DESC LIMIT 500");}
 @Transactional public void importRows(CurrentUser u,String type,List<Map<String,Object>>rows){role(u,"ADMIN");require(!rows.isEmpty()&&rows.size()<=1000,"单次导入1到1000条");for(int i=0;i<rows.size();i++){try{switch(type){case "users":saveUser(u,null,rows.get(i));break;case "assignments":assign(u,rows.get(i));break;case "buildings":case "rooms":case "beds":resource(u,type,null,rows.get(i));break;default:throw new BizException(400,"不支持该导入类型");}}catch(RuntimeException e){throw new BizException(400,"第"+(i+1)+"条导入失败，整批未保存："+e.getMessage());}}}
}
